B=[
('السَّمَاءُ','Gökyüzü',[
('ثُمَّ نَظَرَ إِلَى الْأَجْسَامِ السَّمَاوِيَّةِ، فَرَأَى الشَّمْسَ وَالْقَمَرَ وَالْكَوَاكِبَ تَطْلُعُ مِنَ الْمَشْرِقِ وَتَغْرُبُ فِي الْمَغْرِبِ.','Sonra gök cisimlerine baktı; güneşin, ayın ve yıldızların doğudan doğup batıda battığını gördü.'),
('وَرَأَى حَرَكَتَهَا عَلَى نِظَامٍ لَا يَخْتَلُّ، وَمَقَادِيرَ لَا تَتَبَدَّلُ.','Hareketlerinin bozulmayan bir düzen ve değişmeyen ölçüler üzere olduğunu gördü.'),
('فَعَلِمَ أَنَّ السَّمَاءَ وَمَا فِيهَا كَشَيْءٍ وَاحِدٍ مُتَّصِلٍ بَعْضُهُ بِبَعْضٍ.','Göğün ve içindekilerin, parçaları birbirine bağlı tek bir şey gibi olduğunu anladı.'),
('وَأَنَّ الْعَالَمَ بِأَسْرِهِ كَشَخْصٍ وَاحِدٍ.','Ve bütün âlemin tek bir şahıs gibi olduğunu.'),
('ثُمَّ فَكَّرَ: هَلِ الْعَالَمُ قَدِيمٌ أَمْ حَادِثٌ؟ فَلَمْ يَتَرَجَّحْ عِنْدَهُ أَحَدُ الرَّأْيَيْنِ.','Sonra düşündü: Âlem kadîm midir yoksa sonradan mı olmuştur? İki görüşten hiçbiri onun nezdinde ağır basmadı.'),
('وَلَكِنَّهُ رَأَى أَنَّهُ عَلَى كِلَا الْوَجْهَيْنِ لَا بُدَّ لَهُ مِنْ فَاعِلٍ غَيْرِ جِسْمٍ.','Ama iki durumda da onun cisim olmayan bir fâili olması gerektiğini gördü.'),
('فَإِنْ كَانَ حَادِثًا فَلَهُ مُحْدِثٌ، وَإِنْ كَانَ قَدِيمًا فَحَرَكَتُهُ الدَّائِمَةُ لَا بُدَّ لَهَا مِنْ مُحَرِّكٍ.','Sonradan olmuşsa onun bir meydana getireni vardır; kadîmse sürekli hareketinin mutlaka bir hareket ettiricisi olmalıdır.')]),
('الْوَاجِبُ الْوُجُودِ','Varlığı zorunlu olan',[
('فَعَلِمَ أَنَّ هَذَا الْفَاعِلَ هُوَ وَاجِبُ الْوُجُودِ، الَّذِي وُجُودُ كُلِّ شَيْءٍ مِنْهُ.','Bu fâilin, her şeyin varlığının kendisinden olduğu, varlığı zorunlu olan olduğunu anladı.'),
('وَأَنَّهُ لَا يُدْرَكُ بِالْحِسِّ وَلَا بِالْخَيَالِ، لِأَنَّهُ لَيْسَ بِجِسْمٍ.','Ve O’nun duyuyla da hayalle de idrak edilmediğini, çünkü cisim olmadığını.'),
('وَرَأَى فِي كُلِّ شَيْءٍ أَثَرَ صُنْعِهِ، مِنْ حِكْمَةٍ وَإِتْقَانٍ.','Her şeyde O’nun sanatının izini, hikmet ve mükemmelliği gördü.'),
('حَتَّى فِي أَصْغَرِ الْحَيَوَانِ وَأَحْقَرِ النَّبَاتِ.','En küçük hayvanda ve en değersiz bitkide bile.'),
('فَتَحَقَّقَ أَنَّ ذَلِكَ لَا يَصْدُرُ إِلَّا عَنْ فَاعِلٍ مُخْتَارٍ فِي غَايَةِ الْكَمَالِ.','Bunun ancak kemalin son noktasında, dilediğini yapan bir fâilden çıkabileceğini kesin olarak bildi.'),
('فَتَعَلَّقَ قَلْبُهُ بِهِ، وَانْصَرَفَ عَنِ التَّفْكِيرِ فِي الْأَشْيَاءِ إِلَى التَّفْكِيرِ فِيهِ.','Kalbi O’na bağlandı ve eşyayı düşünmekten O’nu düşünmeye yöneldi.'),
('وَكَانَ قَدْ بَلَغَ مِنْ عُمُرِهِ خَمْسًا وَثَلَاثِينَ سَنَةً.','O sırada yaşı otuz beşe ulaşmıştı.')]),
('بِأَيِّ شَيْءٍ أَدْرَكَهُ؟','O’nu neyle idrak etti?',[
('ثُمَّ سَأَلَ نَفْسَهُ: بِأَيِّ شَيْءٍ أَدْرَكْتُ هَذَا الْمَوْجُودَ؟','Sonra kendine sordu: Bu varlığı neyle idrak ettim?'),
('فَإِنَّ الْحَوَاسَّ لَا تُدْرِكُ إِلَّا الْأَجْسَامَ.','Çünkü duyular ancak cisimleri idrak eder.'),
('فَعَلِمَ أَنَّهُ أَدْرَكَهُ بِذَاتِهِ، وَأَنَّ ذَاتَهُ لَيْسَتْ هِيَ هَذَا الْجَسَدَ.','O’nu kendi özüyle idrak ettiğini ve özünün bu beden olmadığını anladı.'),
('بَلْ هِيَ شَيْءٌ لَا يَفْسُدُ بِفَسَادِ الْجَسَدِ.','Aksine, bedenin bozulmasıyla bozulmayan bir şey olduğunu.'),
('فَرَأَى أَنَّ سَعَادَتَهُ فِي دَوَامِ مُشَاهَدَةِ ذَلِكَ الْمَوْجُودِ.','Mutluluğunun o varlığı sürekli müşahede etmekte olduğunu gördü.'),
('وَأَنَّ شَقَاءَهُ فِي الْبُعْدِ عَنْهُ وَالِاشْتِغَالِ بِغَيْرِهِ.','Ve bedbahtlığının O’ndan uzak kalmakta ve başkasıyla meşgul olmakta olduğunu.'),
('فَأَخَذَ يَتَشَبَّهُ بِالْأَجْرَامِ السَّمَاوِيَّةِ فِي صَفَائِهَا وَدَوَامِ حَرَكَتِهَا.','Saflıklarında ve hareketlerinin sürekliliğinde gök cisimlerine benzemeye başladı.')]),
('الرِّيَاضَةُ','Riyazet',[
('فَأَلْزَمَ نَفْسَهُ أَلَّا يَأْكُلَ إِلَّا مَا يَسُدُّ بِهِ رَمَقَهُ.','Kendine ancak hayatta kalmasına yetecek kadar yemeyi zorunlu kıldı.'),
('وَأَلَّا يَقْطَعَ ثَمَرَةً قَبْلَ أَنْ تَنْضَجَ، وَلَا يُفْسِدَ نَبَاتًا وَلَا يُؤْذِيَ حَيَوَانًا إِلَّا لِحَاجَةٍ.','Olgunlaşmadan bir meyveyi koparmamayı, ihtiyaç olmadıkça bir bitkiyi bozmamayı ve bir hayvana eziyet etmemeyi.'),
('وَكَانَ إِذَا رَأَى نَبَاتًا عَطْشَانَ سَقَاهُ، وَإِذَا رَأَى حَيَوَانًا مَحْبُوسًا خَلَّصَهُ.','Susuz bir bitki görse onu sular, hapsolmuş bir hayvan görse onu kurtarırdı.'),
('وَكَانَ يُنَظِّفُ جَسَدَهُ وَثِيَابَهُ، وَيَتَطَيَّبُ بِالرَّوَائِحِ الطَّيِّبَةِ.','Bedenini ve elbiselerini temizler, güzel kokularla kokulanırdı.'),
('ثُمَّ كَانَ يَدُورُ حَوْلَ بَيْتِهِ كَمَا تَدُورُ الْأَفْلَاكُ.','Sonra feleklerin döndüğü gibi evinin etrafında dönerdi.'),
('ثُمَّ يُغْمِضُ عَيْنَيْهِ، وَيَسُدُّ أُذُنَيْهِ، وَيُجْمِعُ هَمَّهُ عَلَى الْفِكْرَةِ فِي الْوَاجِبِ الْوُجُودِ.','Sonra gözlerini kapar, kulaklarını tıkar ve bütün himmetini varlığı zorunlu olan hakkındaki tefekküre toplardı.'),
('حَتَّى بَلَغَ حَالًا لَا تَصِفُهَا الْأَلْسِنَةُ، وَلَا يُحِيطُ بِهَا الْكَلَامُ.','Sonunda dillerin vasfedemeyeceği, sözün kuşatamayacağı bir hâle ulaştı.')]),
('أَبْسَالُ','Absâl',[
('وَكَانَ فِي الْجَزِيرَةِ الْعَامِرَةِ الْقَرِيبَةِ مِلَّةٌ مِنَ الْمِلَلِ الصَّحِيحَةِ.','Yakındaki meskûn adada doğru dinlerden bir din vardı.'),
('وَنَشَأَ فِيهَا فَتَيَانِ مِنْ أَهْلِ الْفَضْلِ: أَبْسَالُ وَسَلَامَانُ.','Orada fazilet ehlinden iki genç yetişti: Absâl ve Salâmân.'),
('وَكَانَ أَبْسَالُ أَشَدَّ غَوْصًا عَلَى الْبَاطِنِ، وَأَكْثَرَ مَيْلًا إِلَى الْعُزْلَةِ وَالتَّأْوِيلِ.','Absâl bâtına daha derinden dalan, uzlete ve tevile daha çok meyleden biriydi.'),
('وَكَانَ سَلَامَانُ أَكْثَرَ مُلَازَمَةً لِلظَّاهِرِ، وَأَحْرَصَ عَلَى مُخَالَطَةِ النَّاسِ.','Salâmân ise zâhire daha çok bağlı, insanlarla kaynaşmaya daha düşkündü.'),
('فَسَمِعَ أَبْسَالُ بِالْجَزِيرَةِ الْخَالِيَةِ، فَعَزَمَ أَنْ يَرْتَحِلَ إِلَيْهَا لِيَنْقَطِعَ لِلْعِبَادَةِ.','Absâl ıssız adayı duydu ve ibadete kendini vermek için oraya göçmeye karar verdi.'),
('فَفَرَّقَ مَالَهُ عَلَى الْفُقَرَاءِ، وَرَكِبَ سَفِينَةً، فَحَمَلَتْهُ إِلَى سَاحِلِ تِلْكَ الْجَزِيرَةِ.','Malını fakirlere dağıttı, bir gemiye bindi ve gemi onu o adanın kıyısına taşıdı.'),
('فَأَقَامَ فِيهَا يَعْبُدُ اللَّهَ وَيَأْكُلُ مِنْ ثِمَارِهَا، وَهُوَ لَا يَظُنُّ أَنَّ فِيهَا أَحَدًا.','Orada Allah’a ibadet ederek ve meyvelerinden yiyerek kaldı; içinde kimse olduğunu sanmıyordu.')]),
('اللِّقَاءُ','Karşılaşma',[
('فَبَيْنَمَا حَيٌّ يَتَجَوَّلُ يَوْمًا، إِذْ رَأَى أَبْسَالَ، فَتَعَجَّبَ مِنْ صُورَتِهِ.','Bir gün Hayy dolaşırken Absâl’i gördü ve onun suretine şaştı.'),
('فَإِنَّهُ لَمْ يَرَ مِثْلَهُ مِنَ الْحَيَوَانِ قَطُّ.','Çünkü hayvanlar arasında onun benzerini hiç görmemişti.'),
('وَرَأَى عَلَيْهِ ثِيَابًا مِنْ صُوفٍ، وَعَلِمَ أَنَّهَا لَيْسَتْ مِنْ جِلْدِهِ.','Üzerinde yünden elbiseler gördü ve onların kendi derisi olmadığını anladı.'),
('فَخَافَ أَبْسَالُ مِنْهُ وَفَرَّ، لِأَنَّهُ رَأَى رَجُلًا ذَا شَعَرٍ طَوِيلٍ وَجُلُودٍ.','Absâl ondan korktu ve kaçtı; çünkü uzun saçlı ve deriler giymiş bir adam görmüştü.'),
('فَتَبِعَهُ حَيٌّ بِرِفْقٍ، وَأَظْهَرَ لَهُ الْأُنْسَ، حَتَّى سَكَنَ رَوْعُهُ.','Hayy onu yumuşaklıkla izledi ve ona yakınlık gösterdi; sonunda korkusu yatıştı.'),
('فَكَلَّمَهُ أَبْسَالُ بِلُغَاتٍ كَثِيرَةٍ، فَلَمْ يَفْهَمْ حَيٌّ شَيْئًا، وَلَكِنَّهُ أَحَسَّ فِي صَوْتِهِ رِقَّةً.','Absâl onunla birçok dilde konuştu; Hayy hiçbir şey anlamadı ama sesinde bir incelik hissetti.'),
('فَأَطْعَمَهُ أَبْسَالُ مِنْ زَادٍ كَانَ مَعَهُ، فَلَمْ يَسْتَطِبْهُ حَيٌّ، لِأَنَّهُ لَمْ يَعْهَدْهُ.','Absâl ona yanındaki azıktan yedirdi; Hayy onu beğenmedi, çünkü ona alışık değildi.')]),
('التَّعْلِيمُ','Öğretme',[
('فَأَخَذَ أَبْسَالُ يُعَلِّمُهُ الْكَلَامَ، يُشِيرُ إِلَى الْأَشْيَاءِ وَيُسَمِّيهَا.','Absâl ona konuşmayı öğretmeye başladı; eşyayı gösterip onlara isim veriyordu.'),
('حَتَّى تَكَلَّمَ حَيٌّ فِي أَقْرَبِ مُدَّةٍ.','Sonunda Hayy çok kısa bir sürede konuştu.'),
('فَسَأَلَهُ أَبْسَالُ عَنْ شَأْنِهِ، فَحَكَى لَهُ قِصَّتَهُ مِنْ أَوَّلِهَا.','Absâl ona durumunu sordu; o da ona hikâyesini baştan anlattı.'),
('وَوَصَفَ لَهُ مَا أَدْرَكَهُ بِالْفِكْرِ مِنْ أَمْرِ الْوَاجِبِ الْوُجُودِ وَالذَّاتِ وَالسَّعَادَةِ.','Ve ona tefekkürle varlığı zorunlu olan, öz ve mutluluk hakkında idrak ettiklerini vasfetti.'),
('فَلَمَّا سَمِعَ أَبْسَالُ ذَلِكَ، رَأَى أَنَّ جَمِيعَ مَا وَرَدَ فِي شَرِيعَتِهِ مِنْ أَمْرِ اللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَالْيَوْمِ الْآخِرِ هِيَ أَمْثِلَةٌ لِهَذِهِ الْحَقَائِقِ.','Absâl bunu duyunca şeriatında Allah, melekleri, kitapları ve ahiret günü hakkında gelen her şeyin bu hakikatlerin misalleri olduğunu gördü.'),
('فَتَطَابَقَ عِنْدَهُ الْمَعْقُولُ وَالْمَنْقُولُ، وَانْفَتَحَتْ لَهُ أَبْوَابُ الْفَهْمِ.','Onun nezdinde akıl ile nakil örtüştü ve ona anlayışın kapıları açıldı.'),
('وَحَكَى لَهُ أَبْسَالُ أَمْرَ جَزِيرَتِهِ وَأَهْلِهَا، وَمَا هُمْ عَلَيْهِ مِنَ الدِّينِ.','Absâl da ona kendi adasını, halkını ve onların üzerinde bulundukları dini anlattı.')]),
('الرِّحْلَةُ إِلَى النَّاسِ','İnsanlara yolculuk',[
('فَأَشْفَقَ حَيٌّ عَلَى النَّاسِ، وَطَمِعَ أَنْ يَكُونَ نَجَاتُهُمْ عَلَى يَدِهِ.','Hayy insanlara acıdı ve onların kurtuluşunun kendi eliyle olmasını umdu.'),
('فَرَكِبَا سَفِينَةً وَوَصَلَا إِلَى الْجَزِيرَةِ الْعَامِرَةِ.','İkisi bir gemiye binip meskûn adaya vardılar.'),
('وَكَانَ سَلَامَانُ قَدْ صَارَ مَلِكَهَا، فَأَكْرَمَهُمَا.','Salâmân onun kralı olmuştu; ikisine ikram etti.'),
('فَأَخَذَ حَيٌّ يُعَلِّمُ أَصْحَابَ سَلَامَانَ، وَيَكْشِفُ لَهُمْ أَسْرَارَ الْحِكْمَةِ.','Hayy Salâmân’ın arkadaşlarına öğretmeye ve onlara hikmetin sırlarını açmaya başladı.'),
('فَمَا هُوَ إِلَّا أَنْ تَرَقَّى عَنِ الظَّاهِرِ قَلِيلًا، حَتَّى انْقَبَضُوا مِنْهُ وَنَفَرَتْ نُفُوسُهُمْ.','Zâhirden biraz yükselir yükselmez ondan çekindiler ve gönülleri ürktü.'),
('وَرَأَى أَكْثَرَهُمْ مَشْغُولِينَ بِالدُّنْيَا، لَا يَزِيدُهُمُ الْكَلَامُ إِلَّا بُعْدًا.','Çoğunu dünyayla meşgul gördü; söz onları yalnızca daha da uzaklaştırıyordu.'),
('فَعَلِمَ أَنَّ لِكُلِّ قَوْمٍ مَقَامًا، وَأَنَّ الشَّرِيعَةَ الَّتِي جَاءَتْهُمْ هِيَ الْأَنْسَبُ لَهُمْ.','Her topluluğun bir makamı olduğunu ve onlara gelen şeriatın onlar için en uygun olan olduğunu anladı.')]),
('الْعَوْدَةُ','Dönüş',[
('فَجَاءَ إِلَى سَلَامَانَ وَأَصْحَابِهِ، فَاعْتَذَرَ إِلَيْهِمْ مِمَّا تَكَلَّمَ بِهِ.','Salâmân’a ve arkadaşlarına geldi ve söylediklerinden dolayı onlardan özür diledi.'),
('وَأَوْصَاهُمْ بِمُلَازَمَةِ مَا هُمْ عَلَيْهِ مِنَ الشَّرْعِ، وَالْإِيمَانِ بِمُتَشَابِهِهِ، وَالتَّسْلِيمِ لَهُ.','Onlara üzerinde bulundukları şeriata bağlı kalmalarını, müteşabihine iman edip ona teslim olmalarını tavsiye etti.'),
('وَأَمَرَهُمْ أَنْ يَتْرُكُوا الْبِدَعَ وَالْأَهْوَاءَ، وَأَنْ يَقْتَدُوا بِالسَّلَفِ الصَّالِحِ.','Onlara bidatleri ve hevaları bırakmalarını ve salih seleflere uymalarını emretti.'),
('ثُمَّ وَدَّعَهُمْ، وَرَجَعَ هُوَ وَأَبْسَالُ إِلَى جَزِيرَتِهِ.','Sonra onlarla vedalaştı; o ve Absâl kendi adasına döndüler.'),
('فَعَبَدَا اللَّهَ فِيهَا حَتَّى أَتَاهُمَا الْيَقِينُ.','Ölüm gelinceye kadar orada Allah’a ibadet ettiler.'),
('قَالَ ابْنُ طُفَيْلٍ: هَذَا مَا تَيَسَّرَ مِنْ خَبَرِ حَيِّ بْنِ يَقْظَانَ.','İbn Tufeyl der ki: Hayy b. Yakzân’ın haberinden kolaylaşan bu kadardır.'),
('وَفِيهِ عِبْرَةٌ لِمَنْ لَهُ قَلْبٌ، أَوْ أَلْقَى السَّمْعَ وَهُوَ شَهِيدٌ.','Onda kalbi olan ya da şahit olarak kulak veren için bir ibret vardır.')]),
]
